#include <Servo.h>

Servo servo; // Crea el objeto servo

void setup() {
    servo.attach(9); // Asigna el pin 9 al servo
}

void loop() {
    servo.write(0);   // Mueve a 0 grados
    delay(1000);     // Espera 1 segundo

    servo.write(90);  // Mueve a 90 grados
    delay(1000);     // Espera 1 segundo

    servo.write(180); // Mueve a 180 grados
    delay(1000);     // Espera 1 segundo
}
